// ════════════════════════════════════════════════════════════════════════
// tools/lib/generated-target.mjs — WHICH FILE A CATALOGUE GENERATOR OWNS NOW.
//
// A generator's output is the NEWEST migration in tests/schema-apply-order.json
// that it wrote (its own "Generated by tools/<tool>" header line), never a
// hard-coded date: two lanes that each add a forward file (2026-10-26 slot
// starter, 2026-10-27 core rebuild) then agree on which one `--check` grades.
//
// An APPLIED file is never rewritten (CLAUDE.md §2: production runs it as it
// was reviewed). When the newest owned file is APPLIED, a write is refused and
// names the way forward: `--new <YYYY-MM-DD-name>.generated.sql` writes a NEW
// file, which the author then places in the apply order with a STAGED note.
// ════════════════════════════════════════════════════════════════════════
import { readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';

/**
 * @param {string} root  the repo root
 * @param {string} tool  e.g. 'gen-unlocks.mjs'
 * @returns {{ file: string, path: string, applied: boolean } | null}
 */
export function newestOwned(root, tool) {
  const manifest = JSON.parse(readFileSync(join(root, 'tests', 'schema-apply-order.json'), 'utf8'));
  const sig = 'Generated by tools/' + tool;
  for (let i = manifest.order.length - 1; i >= 0; i--) {
    const file = manifest.order[i];
    const path = join(root, 'supabase', 'migrations', file);
    if (!existsSync(path) || !readFileSync(path, 'utf8').includes(sig)) continue;
    const note = (manifest._order_notes || {})[file];
    return { file, path, applied: typeof note === 'string' && /^APPLIED\b/.test(note) };
  }
  return null;
}

/**
 * Where a generator writes (or checks): `--new <file>` for a new forward file,
 * else the newest owned file. `write` refuses an APPLIED target.
 * @returns {string} the absolute path
 */
export function generatedTarget(root, tool, argv, { write, die }) {
  const at = argv.indexOf('--new');
  if (at >= 0) {
    const name = argv[at + 1] || '';
    if (!/^\d{4}-\d{2}-\d{2}-[a-z0-9-]+\.generated\.sql$/.test(name)) die('--new wants a YYYY-MM-DD-<name>.generated.sql file name');
    const path = join(root, 'supabase', 'migrations', name);
    if (existsSync(path)) die(name + ' already exists; --new is for a NEW forward file');
    return path;
  }
  const t = newestOwned(root, tool);
  if (!t) die('no migration in tests/schema-apply-order.json carries "Generated by tools/' + tool + '"');
  if (write && t.applied) {
    die(t.file + ' is APPLIED and is never rewritten. Run: node tools/' + tool
      + ' --new <YYYY-MM-DD-name>.generated.sql, then place that file in tests/schema-apply-order.json with a STAGED note');
  }
  return t.path;
}
